test.each(cases)(
	"recovery rejects a restored receipt %s mismatch before inventory or process effects #test-519",
	async (name) => {
		const fixture = fixtures.get(name)!;
		const inventory = mock(() => Promise.reject(new Error("Unexpected inventory refresh")));
