test("stopped root releases owned descendants while preserving protected and related work #test-559", async () => {
	const { tracker, root, descendant, untouched, before, scope, request } = hierarchyFixture;
	const evidence = operationEvidence();
	await releaseClaims(
		tracker,
		{ ...request, context: { ...request.context, claims: [root] } },
		evidence,
	);
	const released = await tracker.beads.showMany(scope, [root, descendant]);
	expect(released.map(({ owner, status, assignee }) => ({ owner, status, assignee }))).toEqual([
		{ owner: "ct", status: "open", assignee: undefined },
		{ owner: "ct", status: "blocked", assignee: undefined },
	]);
	const preserved = await tracker.beads.showMany(scope, untouched);
	expect(preserved.map(({ updated_at }) => updated_at)).toEqual(
		before.map(({ updated_at }) => updated_at),
	);
	expect(evidence.effects).toEqual([`tracker.released:${root}`, `tracker.released:${descendant}`]);
});

test("submission rejects human reservations and admits one open request per task #test-412", async () => {
	const context = commands(admission);
	await expect(
		spawnWorkflowRequest(
			{ kind: "worker", assignment: { kind: "driver", runId: reserved }, options },
			context,
		),
	).rejects.toBeInstanceOf(Error);
	await expect(
		validateRequestedTasks({ requestedIds: [reserved], options }, context),
	).rejects.toBeInstanceOf(Error);
	const created = await spawnWorkflowRequest(
		{ kind: "worker", assignment: { kind: "driver", runId: task }, options },
		context,
	);
	const request = await admission.beads.show(
		trackerScope(admission.repository, "inspector"),
		created.request.id,
	);
	expect(request.owner).toBe("ct");
	expect(request.assignee).toBe(created.request.assignee);
	expect(request.dependencies.map(({ id, dependency_type }) => ({ id, dependency_type }))).toEqual([
		{ id: task, dependency_type: "related" },
	]);
	await expect(
		spawnWorkflowRequest(
			{ kind: "worker", assignment: { kind: "driver", runId: task }, options },
			context,
		),
	).rejects.toBeInstanceOf(Error);
	await expect(
		validateRequestedTasks({ requestedIds: [task], options }, context),
	).rejects.toBeInstanceOf(Error);
});

