test.each(closureCases)(
	"$caller closes proven tasks after the Land run (completeParent: $completeParent) #test-368",
	// Verify durable evidence and caller ordering as one lifecycle.
	// eslint-disable-next-line max-statements
	async (entry) => {
		const { beads, io, run, scope, parent, completed, order } = closureRuns.get(
			JSON.stringify(entry),
		)!;
		const stage = run.active[FIRST]!.bead;
		expect(await beads.show(scope, completed)).toMatchObject({ status: "open" });
		expect(await beads.comments.list(scope, run.id)).toMatchObject([{ text: evidence }]);
		await beads.close(scope, stage);
		const done = await navigate({ id: run.id, operation: "collect" }, {}, io);
		expect(done).toMatchObject({ status: "done", active: [] });
		expect(await beads.show(scope, run.id)).toMatchObject({ status: "closed" });
		expect(await beads.show(scope, completed)).toMatchObject({ status: "open" });
		await beads.close(scope, completed, { reason: evidence });
		order.push("SIMULATED final publication");
		expect(order).toEqual([stage, run.id, completed, "SIMULATED final publication"]);
		let parentStatus = "open";
		if (entry.completeParent) {
			parentStatus = "closed";
		}
		expect(await beads.show(scope, parent)).toMatchObject({ status: parentStatus });
	},
);

test("claims retain human owners and release only unfinished tasks still owned by this bee #test-558", async () => {
	const { tracker, id, foreign, closed, request } = releaseFixture;
	const evidence = operationEvidence();
	expect(await acquireClaim(tracker, "worker", id, evidence)).toBe("claimed");
	expect(await tracker.beads.show(trackerScope(tracker.repository, "inspector"), id)).toMatchObject(
		{
			assignee: "worker",
			owner: "ct",
			status: "in_progress",
		},
	);
	await releaseClaims(
		{
			...tracker,
			beads: beforeTrackerWrite(tracker.beads, (scope) => {
				expect(scope.actor).toBe("sys-colony");
				return Promise.resolve();
			}),
		},
		{ ...request, context: { ...request.context, claims: [id, foreign, closed] } },
		evidence,
	);
	const released = await tracker.beads.show(trackerScope(tracker.repository, "inspector"), id);
	expect(released.assignee).toBeUndefined();
	expect(released).toMatchObject({ owner: "ct", status: "open" });
	expect(
		await tracker.beads.show(trackerScope(tracker.repository, "inspector"), foreign),
	).toMatchObject({
		assignee: "another-bee",
		status: "in_progress",
	});
	const untouched = await tracker.beads.show(trackerScope(tracker.repository, "inspector"), closed);
	expect(untouched.status).toBe("closed");
	expect(evidence.effects).toEqual([`tracker.claimed:${id}`, `tracker.released:${id}`]);
});

test.each(parentedFixtures)(
	"$role cleanup stays beneath its captured claim in a parented workflow #test-563",
	// Verify release, preserved records and the next identity's role-scoped reacquisition.
	// eslint-disable-next-line max-statements
	async ({ tracker, root, child, visit, role, scope, untouched, before, request }) => {
		await releaseClaims(
			tracker,
			{ ...request, context: { ...request.context, claims: [root] } },
			operationEvidence(),
		);
		const released = [root, child];
		if (role === "driver") {
			released.push(visit);
		}
		const releasedRecords = await tracker.beads.showMany(scope, released);
		const preserved = await tracker.beads.showMany(scope, untouched);
		expect(
			releasedRecords.map(({ status, assignee }) => ({
				status,
				assignee,
			})),
		).toEqual(released.map(() => ({ status: "open", assignee: undefined })));
		expect(
			preserved.map(
				({ dependencies: _dependencies, dependents: _dependents, ...record }) => record,
			),
		).toEqual(
			before.map(({ dependencies: _dependencies, dependents: _dependents, ...record }) => record),
		);
		expect(await acquireClaim(tracker, "replacement", root, operationEvidence())).toBe("claimed");
		if (role === "driver") {
			expect(await acquireClaim(tracker, "replacement", visit, operationEvidence())).toBe(
				"claimed",
			);
		}
	},
);

test.each(cancelled)(
	"$kind cancellation requires opt-in and retains native history on replacement and repetition #test-429",
	// Verify the public replacement and retained native facts as one recovery boundary.
	// eslint-disable-next-line max-statements
	async ({ assignment, tracker, scope, original }) => {
		const context = commands(tracker);
		await expect(retryRequest(original.id, options, context)).rejects.toBeInstanceOf(Error);
		const replacement = await retryRequest(
			original.id,
			{ ...options, resumeCancelled: true, model: "current-override" },
			context,
		);
		const request = readSpawnRequest(await tracker.beads.show(scope, replacement.request.id));
		expect(request).toMatchObject({
			assignment,
			host: hostname(),
			recipe: { model: "current-override" },
		});
		expect(request.identity).not.toBe(original.assignee);
		expect(request.taskIds).toEqual(readSpawnRequest(original).taskIds);
		const retained = await tracker.beads.show(scope, original.id);
		expect(retained).toMatchObject({
			status: "closed",
			close_reason: original.close_reason,
			closed_at: original.closed_at,
			assignee: original.assignee,
			description: original.description,
		});
		expect(requestDisposition(retained)).toEqual({ outcome: "cancelled", resolution: "resolved" });
		expect(requestNeedsAttention(retained)).toBe(false);
		expect(requestResolution(retained)).toEqual({
			kind: "superseded",
			replacementIds: [request.id],
		});
		await expect(
			retryRequest(original.id, { ...options, resumeCancelled: true }, context),
		).rejects.toBeInstanceOf(Error);
		const repeated = await tracker.beads.show(scope, original.id);
		expect(repeated.dependents).toEqual(retained.dependents);
	},
);

test.each(refusals)(
