import { complete, navigate, start } from "../../src/runtime.ts";
import { expect, test } from "bun:test";
import { createMachine } from "xstate";
import { createMemoryBeads } from "@hive/beads";
import { createServices } from "../../src/native.ts";
import { readCheckpoint } from "../../src/checkpoint.ts";
import { z } from "zod";

const FIRST = 0;
const RUN_ARGUMENT = 6;
const scope = { cwd: "/managed-exposure", db: "/managed-exposure/beads.db", actor: "worker" };
const definition = {
	inputSchema: z.object({}),
	commandSchemas: { next: z.object({}) },
	runBrief: () => ({ title: "Exposure", description: "Managed exposure" }),
	machine: createMachine({
		id: "exposure",
		initial: "prepare",
		states: {
			prepare: {
				meta: {
					title: "Prepare",
					commands: { next: "NEXT" },
					task: () => ({ instructions: "Prepare" }),
				},
				on: { NEXT: "work" },
			},
			work: {
				meta: {
					title: "Work",
					commands: { next: "NEXT" },
					task: () => ({ instructions: "Work", bee: { kind: "worker" } }),
				},
				on: { NEXT: "done" },
			},
			done: { type: "final" },
		},
	}),
};
