	execute: async (argv: string[]) => {
		const current = await beads.show(scope, argv[RUN_ARGUMENT]!);
		const checkpoint = await beads.show(
			scope,
			current.dependencies.find((edge) => edge.dependency_type === "related")!.id,
		);
		const prior = readCheckpoint(checkpoint);
		observations.push({
			managedExecution: prior.managedExecution,
			active: prior.active,
			created: prior.created,
			locked: checkpoint.notes !== "",
		});
		return JSON.stringify({ ok: true, request: { id: "request" } });
	},
};
