const checkpoint = await beads.show(
	scope,
	nativeRun.dependencies.find((edge) => edge.dependency_type === "related")!.id,
);
const prior = readCheckpoint(checkpoint);

test("rendered managed dispatch stamps the coherent prior checkpoint before request effects", async () => {
