	const { actor, clock, calls, finish } = visibility;
	actor.send({ type: "HIDE" });
	clock.increment(REFRESH_INTERVAL_MS);
	expect(calls()).toBe(0);
	actor.send({ type: "SHOW" });
	expect(calls()).toBe(1);
	actor.send({ type: "HIDE" });
	actor.send({ type: "SHOW" });
	expect(calls()).toBe(1);
	actor.send({ type: "HIDE" });
	await finish();
	actor.send({ type: "SHOW" });
	expect(calls()).toBe(TWO_CYCLES);
	actor.stop();
});

