const authorityCases = authorityChanges
	.flatMap((change) => [
		{ change, point: "after-fact" as const, seed: "empty" as const },
		{ change, point: "after-fact" as const, seed: "stdout" as const },
	])
	.filter(({ change, seed }) => change !== "kind" || seed !== "empty");
